begin;
set local search_path=public,extensions;
select plan(32);

select ok((select count(*)=6 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['admin_queue_versions','admin_work_items','admin_work_item_events','admin_operational_action_requests','admin_operational_action_decisions','admin_support_access_grants'])),'six command-center tables exist');
select ok(to_regclass('private.admin_command_keys')is not null,'admin idempotency keys use a private table');
select ok((select count(*)=6 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['admin_queue_versions','admin_work_items','admin_work_item_events','admin_operational_action_requests','admin_operational_action_decisions','admin_support_access_grants'])),'RLS is enabled on every public command-center table');
select ok((select count(*)=6 from pg_policies where schemaname='public'and tablename=any(array['admin_queue_versions','admin_work_items','admin_work_item_events','admin_operational_action_requests','admin_operational_action_decisions','admin_support_access_grants'])),'all command-center tables have explicit read policies');
select ok(not has_table_privilege('authenticated','public.admin_work_items','INSERT')and not has_table_privilege('authenticated','public.admin_operational_action_requests','UPDATE'),'authenticated cannot bypass admin commands with direct writes');
select ok(not has_table_privilege('service_role','public.admin_work_items','INSERT')and not has_table_privilege('service_role','private.admin_command_keys','SELECT'),'service role has no broad direct table bypass');
select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['open_admin_work_item','claim_admin_work_item','resolve_admin_work_item','request_admin_operational_action','decide_admin_operational_action'])),'five human commands are security definer with fixed search paths');
select ok((select prosecdef and proconfig::text like'%search_path=%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_admin_operational_action'),'worker completion is security definer with fixed search path');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['open_admin_work_item','claim_admin_work_item','resolve_admin_work_item','request_admin_operational_action','decide_admin_operational_action'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'human commands exclude anon and service roles');
select ok((select has_function_privilege('service_role',p.oid,'EXECUTE')and not has_function_privilege('authenticated',p.oid,'EXECUTE')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_admin_operational_action'),'only service role can record an authorized execution');
select ok((select count(*)=4 from public.admin_queue_versions where status='ACTIVE'),'executive, approvals, exceptions and risk queues are seeded');
select ok((select label_fr='À traiter aujourd’hui'and label_ar<>''and sort_weight=100 from public.admin_queue_versions where queue_key='EXECUTIVE_TODAY'and status='ACTIVE'),'today queue is bilingual and highest-level prioritized');
select ok((select count(*)=3 from pg_trigger where tgname=any(array['admin_queue_versions_immutable','admin_work_events_immutable','admin_action_decisions_immutable'])and not tgisinternal),'configuration versions, work history and decisions are immutable');
select ok((select is_generated='ALWAYS'from information_schema.columns where table_schema='public'and table_name='admin_work_items'and column_name='severity_rank'),'severity rank is deterministic and stored');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and indexname='admin_today_priority_idx'and indexdef like'%severity_rank DESC%due_at%'),'today work is indexed by severity then deadline');
select ok((select pg_get_functiondef(p.oid)like'%required_role_codes%'and pg_get_functiondef(p.oid)like'%has_platform_role%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='admin_has_queue_access'),'queue access is role-scoped rather than a generic admin bypass');
select ok((select pg_get_functiondef(p.oid)like'%READ_ONLY_AUDITOR%'and pg_get_functiondef(p.oid)like'%ADMIN_WORK_CLAIM_DENIED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='claim_admin_work_item'),'read-only auditors cannot claim work');
select ok((select pg_get_functiondef(p.oid)like'%assigned_to is distinct from a%'and pg_get_functiondef(p.oid)like'%HUMAN_RESOLUTION%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='resolve_admin_work_item'),'resolution is an assigned, explicit human decision');
select ok((select pg_get_functiondef(p.oid)like'%STALE_ADMIN_WORK_ITEM%'and pg_get_functiondef(p.oid)like'%row_version%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='claim_admin_work_item'),'claim uses optimistic concurrency');
select ok((select pg_get_functiondef(p.oid)like'%begin_admin_command%'and pg_get_functiondef(p.oid)like'%finish_admin_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='open_admin_work_item'),'work opening is idempotent');
select ok((select pg_get_functiondef(p.oid)like'%p_redacted_context?|%'and pg_get_functiondef(p.oid)like'%api_key%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='open_admin_work_item'),'work context rejects common secret-bearing keys');
select ok((select pg_get_functiondef(p.oid)like'%approvals_required%'and pg_get_functiondef(p.oid)like'%RESTRICT_ENTITY%'and pg_get_functiondef(p.oid)like'%SUSPEND_ENTITY%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='request_admin_operational_action'),'restriction and suspension require elevated approval');
select ok((select pg_get_functiondef(p.oid)like'%a=x.requested_by%'and pg_get_functiondef(p.oid)like'%ADMIN_ACTION_DECISION_DENIED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_admin_operational_action'),'requester cannot approve their own action');
select ok((select count(*)=1 from pg_constraint where conrelid='public.admin_operational_action_decisions'::regclass and contype='u'and pg_get_constraintdef(oid)like'%action_request_id%decided_by%'),'one actor cannot supply multiple approvals');
select ok((select pg_get_functiondef(p.oid)like'%pg_advisory_xact_lock%'and pg_get_functiondef(p.oid)like'%STALE_ADMIN_ACTION_REQUEST%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_admin_operational_action'),'concurrent decisions are serialized and stale-safe');
select ok((select pg_get_functiondef(p.oid)like'%AUTHORIZE_PRODUCTION_CHANGE%'and pg_get_functiondef(p.oid)like'%p_production_authorization_reference%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='request_admin_operational_action'),'production requests require an explicit authorization reference');
select ok(exists(select 1 from pg_constraint where conrelid='public.admin_operational_action_requests'::regclass and contype='c'and pg_get_constraintdef(oid)like'%PRODUCTION%'and pg_get_constraintdef(oid)like'%target_environment%'and pg_get_constraintdef(oid)like'%production_authorization_reference%'),'production authorization is structurally constrained');
select ok((select pg_get_functiondef(p.oid)like'%auth.role()<>''service_role''%'and pg_get_functiondef(p.oid)like'%status<>''AUTHORIZED''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_admin_operational_action'),'worker records only explicitly authorized actions');
select ok((select pg_get_constraintdef(oid)like'%01:00:00%'from pg_constraint where conrelid='public.admin_support_access_grants'::regclass and contype='c'and pg_get_constraintdef(oid)like'%expires_at%'),'support grants are time-boxed to one hour');
select ok((select pg_get_functiondef(p.oid)like'%GRANT_SUPPORT_ACCESS%'and pg_get_functiondef(p.oid)like'%admin_support_access_grants%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_admin_operational_action'),'support access is materialized only after authorized completion');
select ok((select pg_get_functiondef(p.oid)like'%AdminActionApprovalRequiredV1%'and pg_get_functiondef(p.oid)like'%event_outbox%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='request_admin_operational_action'),'sensitive action requests emit Outbox events');
select ok((select pg_get_functiondef(p.oid)like'%admin.action.completed%'and pg_get_functiondef(p.oid)like'%AdminActionExecutedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_admin_operational_action'),'worker result is audited and emitted');

select * from finish();
rollback;
